@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-link: var(--link);
  --font-sans: var(--font-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning: var(--warning);
  --color-success-foreground: var(--success-foreground);
  --color-success: var(--success);
  --color-info-foreground: var(--info-foreground);
  --color-info: var(--info);
  --color-destructive-foreground: var(--destructive-foreground);

  /* Semantic: Info */
  --color-info-dark: var(--info-dark);
  --color-info: var(--info);
  --color-info-light: var(--info-light);
  --color-info-lighter: var(--info-lighter);

  /* Semantic: Warning */
  --color-warning-dark: var(--warning-dark);
  --color-warning: var(--warning);
  --color-warning-light: var(--warning-light);
  --color-warning-lighter: var(--warning-lighter);

  /* Semantic: Success */
  --color-success-dark: var(--success-dark);
  --color-success: var(--success);
  --color-success-light: var(--success-light);
  --color-success-lighter: var(--success-lighter);

  /* Semantic: Error */
  --color-error-dark: var(--error-dark);
  --color-error: var(--error);
  --color-error-light: var(--error-light);
  --color-error-lighter: var(--error-lighter);
}

/* ============================================================
   MTN DESIGN SYSTEM — Light Mode
   Primary: oklch(0.86 0.18 92) ≈ #FFCB00 MTN Yellow
   Grey scale: true neutral (no hue cast)
   Accent: soft yellow-tint, not amber
   ============================================================ */
:root {
  /* Canvas */
  --background: oklch(0.99 0 0);                /* pure near-white */
  --foreground: oklch(0.14 0 0);                 /* true dark charcoal */

  /* Cards & Popovers */
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.14 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.14 0 0);

  /* Primary — MTN Yellow */
  --primary: oklch(0.86 0.18 92);               /* #FFCB00 */
  --primary-foreground: oklch(0.14 0 0);        /* dark text on yellow */

  /* Link — accessible deep blue for light mode (contrast ~5:1 on white) */
  --link: oklch(0.14 0 0);

  /* Secondary — clean neutral grey */
  --secondary: oklch(0.95 0 0);
  --secondary-foreground: oklch(0.22 0 0);

  /* Muted — lightest neutral */
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.52 0 0);

  /* Accent — very soft yellow wash, barely there */
  --accent: oklch(0.95 0.04 92);               /* faint yellow tint */
  --accent-foreground: oklch(0.25 0 0);

  /* Destructive */
  --destructive: oklch(0.57 0.22 27);

  /* Borders & Inputs */
  --border: oklch(0.91 0 0);
  --input: oklch(0.93 0 0);
  --ring: oklch(78.974% 0.16126 92.408);

  /* Charts — golden ramp */
  --chart-1: oklch(0.93 0.17 98);
  --chart-2: oklch(65.014% 0.00465 271.347);
  --chart-3: oklch(0.75 0.16 72);
  --chart-4: oklch(0.60 0.13 55);
  --chart-5: oklch(0.35 0.07 45);

  --radius: 0.75rem;

  /* Button depth shadows */
  --button-shadow:           inset 0px 1px 0px oklch(1 0 0 / 33%), inset 0px -1px 0px oklch(0 0 0 / 15%);
  --button-secondary-shadow: inset 0px 1px 0px oklch(1 0 0 / 55%), inset 0px -1px 0px oklch(0 0 0 / 10%);
  --button-outline-shadow:   inset 0px 1px 0px oklch(1 0 0 / 50%), inset 0px -1px 0px oklch(0 0 0 / 8%);

  /* Sidebar */
  --sidebar: oklch(0.975 0 0);
  --sidebar-foreground: oklch(0.14 0 0);
  --sidebar-primary: oklch(0.86 0.18 92);
  --sidebar-primary-foreground: oklch(0.14 0 0);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: oklch(0.91 0 0);
  --sidebar-ring: oklch(0.86 0.18 92);

  /* ── Semantic Colors — Light ─────────────────────────────── */

  /* Info — clear blue */
  --info-dark:    oklch(0.40 0.14 250);
  --info:    oklch(0.55 0.17 250);
  --info-light:   oklch(0.82 0.09 250);
  --info-lighter: oklch(0.95 0.03 250);

  /* Warning — amber, distinct from MTN yellow */
  --warning-dark:    oklch(0.48 0.15 62);
  --warning:    oklch(0.65 0.17 62);
  --warning-light:   oklch(0.85 0.10 80);
  --warning-lighter: oklch(0.96 0.03 88);

  /* Success — clean green */
  --success-dark:    oklch(0.38 0.13 155);
  --success:    oklch(0.54 0.17 155);
  --success-light:   oklch(0.80 0.10 155);
  --success-lighter: oklch(0.95 0.03 155);

  /* Error — vivid red */
  --error-dark:    oklch(0.40 0.18 27);
  --error:    oklch(0.57 0.22 27);
  --error-light:   oklch(0.80 0.10 27);
  --error-lighter: oklch(0.96 0.03 27);
  --destructive-foreground: var(--color-red-700);
}

/* ============================================================
   MTN DESIGN SYSTEM — Dark Mode
   Premium dark: true neutral darks, yellow pops cleanly
   ============================================================ */
.dark {
  /* Canvas */
  --background: oklch(0.13 0 0);               /* true dark neutral */
  --foreground: oklch(0.97 0 0);               /* clean off-white */

  /* Cards & Popovers */
  --card: oklch(0.18 0 0);
  --card-foreground: oklch(0.97 0 0);
  --popover: oklch(0.24 0 0);
  --popover-foreground: oklch(0.97 0 0);

  /* Primary */
  --primary: oklch(0.88 0.18 92);
  --primary-foreground: oklch(0.13 0 0);

  /* Link — primary yellow in dark mode (great contrast on dark bg) */
  --link: oklch(0.88 0.18 92);

  /* Secondary */
  --secondary: oklch(0.23 0 0);
  --secondary-foreground: oklch(0.97 0 0);

  /* Muted */
  --muted: oklch(0.21 0 0);
  --muted-foreground: oklch(0.60 0 0);

  /* Accent — soft yellow wash in dark */
  --accent: oklch(0.28 0.03 92);              /* very muted yellow tint */
  --accent-foreground: oklch(0.97 0 0);

  /* Destructive */
  --destructive: oklch(0.68 0.20 22);

  /* Borders & Inputs */
  --border: oklch(1 0 0 / 9%);
  --input: oklch(1 0 0 / 13%);
  --ring: oklch(0.88 0.18 92);

  /* Charts */
  --chart-1: oklch(0.93 0.17 98);
  --chart-2: oklch(41.582% 0.01435 264.438);
  --chart-3: oklch(0.75 0.16 72);
  --chart-4: oklch(0.60 0.13 55);
  --chart-5: oklch(0.35 0.07 45);

  /* Button depth shadows */
  --button-shadow:           inset 0px 1px 0px oklch(1 0 0 / 15%), inset 0px -1px 0px oklch(0 0 0 / 25%);
  --button-secondary-shadow: inset 0px 1px 0px oklch(1 0 0 / 12%), inset 0px -1px 0px oklch(0 0 0 / 20%);
  --button-outline-shadow:   inset 0px 1px 0px oklch(1 0 0 / 8%),  inset 0px -1px 0px oklch(0 0 0 / 15%);

  /* Sidebar */
  --sidebar: oklch(0.17 0 0);
  --sidebar-foreground: oklch(0.97 0 0);
  --sidebar-primary: oklch(0.88 0.18 92);
  --sidebar-primary-foreground: oklch(0.13 0 0);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: oklch(1 0 0 / 9%);
  --sidebar-ring: oklch(0.88 0.18 92);
  --destructive-foreground: var(--color-red-400);
  /*--info: var(--color-blue-500);
  --info-foreground: var(--color-blue-400);
  --success: var(--color-emerald-500);
  --success-foreground: var(--color-emerald-400);
  --warning: var(--color-amber-500);
  --warning-foreground: var(--color-amber-400);*/

  /* ── Semantic Colors — Dark ──────────────────────────────── */

  /* Info */
  --info-dark:    oklch(0.75 0.13 250);
  --info:    oklch(0.62 0.16 250);
  --info-light:   oklch(0.35 0.10 250);
  --info-lighter: oklch(0.22 0.05 250);

  /* Warning */
  --warning-dark:    oklch(0.85 0.14 80);
  --warning:    oklch(0.72 0.16 68);
  --warning-light:   oklch(0.40 0.10 65);
  --warning-lighter: oklch(0.24 0.05 70);

  /* Success */
  --success-dark:    oklch(0.75 0.14 155);
  --success:    oklch(0.60 0.17 155);
  --success-light:   oklch(0.35 0.10 155);
  --success-lighter: oklch(0.22 0.05 155);

  /* Error */
  --error-dark:    oklch(0.78 0.16 27);
  --error:    oklch(0.65 0.20 27);
  --error-light:   oklch(0.36 0.12 27);
  --error-lighter: oklch(0.22 0.06 27);
}

/* ── Style A: ring + border (original) ─────────────────────────────────────
   Uncomment to use. Applied in: input.tsx, select.tsx */
/*
@utility input-focus-ring {
  &:focus-visible {
    @apply border-ring outline-none ring-[3px] ring-ring/20;
  }
}
*/

/* ── Style A: ring + border (original, container variant) ──────────────────
   Uncomment to use. Applied in: input-group.tsx, combobox.tsx */
/*
@utility input-focus-ring-within {
  &:focus-within {
    @apply border-ring outline-none ring-[3px] ring-ring/20;
  }
}
*/

/* ── Style B: 2px primary bottom border, no bottom radius ──────────────────
   Applied in: input.tsx, select.tsx, textarea.tsx */
@utility input-focus-ring {
  &:focus-visible {
    @apply outline-none border-x-transparent border-t-transparent border-b-2 border-b-primary rounded-b-none bg-input/50;
  }
}

/* ── Style B: 2px primary bottom border, no bottom radius (container) ──────
   Applied in: input-group.tsx, combobox.tsx */
@utility input-focus-ring-within {
  &:focus-within {
    @apply outline-none border-x-transparent border-t-transparent border-b-2 border-b-primary rounded-b-none bg-input/50;
  }
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}
